{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/ed3c/ai-content-notes/schemas/projection-bundle.schema.json",
  "title": "Graph-derived human projection bundle",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "bundle_id",
    "source_graph_digest",
    "projections",
    "created_at"
  ],
  "properties": {
    "schema_version": {
      "const": "projection-bundle@1"
    },
    "bundle_id": {
      "type": "string",
      "minLength": 1
    },
    "source_graph_digest": {
      "$ref": "#/$defs/sha256"
    },
    "projections": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "projection_id",
          "projection_kind",
          "title",
          "source_relation_ids",
          "source_card_ids",
          "visual_evidence_ids",
          "uncertainty_policy",
          "data",
          "rendered"
        ],
        "properties": {
          "projection_id": {
            "type": "string",
            "minLength": 1
          },
          "projection_kind": {
            "enum": [
              "causal-dataflow",
              "comparison-matrix",
              "timeline",
              "state-planes",
              "equation",
              "architecture"
            ]
          },
          "title": {
            "type": "string",
            "minLength": 1
          },
          "source_relation_ids": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "uniqueItems": true
          },
          "source_card_ids": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "uniqueItems": true
          },
          "visual_evidence_ids": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "uniqueItems": true
          },
          "uncertainty_policy": {
            "enum": [
              "LABEL_UNKNOWN",
              "DOTTED_UNCERTAIN_EDGES",
              "OMIT_UNSUPPORTED_VALUES"
            ]
          },
          "rendered": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "markdown",
              "mermaid",
              "ascii"
            ],
            "properties": {
              "markdown": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "mermaid": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "ascii": {
                "type": [
                  "string",
                  "null"
                ]
              }
            }
          },
          "data": {
            "type": [
              "object",
              "null"
            ],
            "description": "Machine-readable projection payload, including comparison-cell provenance when applicable."
          }
        }
      }
    },
    "created_at": {
      "type": "string",
      "format": "date-time"
    }
  },
  "$defs": {
    "sha256": {
      "type": "string",
      "pattern": "^sha256:[a-f0-9]{64}$"
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/ed3c/ai-content-notes/schemas/projection-plan.schema.json",
  "title": "Evidence-bound knowledge projection plan",
  "type": "object",
  "additionalProperties": false,
  "required": ["schema_version", "bundle_id", "source_graph_digest", "projections", "created_at"],
  "properties": {
    "schema_version": {"const": "projection-plan@1"},
    "bundle_id": {"type": "string", "minLength": 1},
    "source_graph_digest": {"$ref": "#/$defs/sha256"},
    "projections": {
      "type": "array",
      "minItems": 1,
      "items": {"$ref": "#/$defs/projection"}
    },
    "created_at": {"type": "string", "format": "date-time"}
  },
  "$defs": {
    "sha256": {"type": "string", "pattern": "^sha256:[a-f0-9]{64}$"},
    "anchorList": {
      "type": "array",
      "items": {"type": "string", "minLength": 1},
      "uniqueItems": true
    },
    "comparisonCell": {
      "type": "object",
      "additionalProperties": false,
      "required": ["value", "status", "evidence_ids", "visual_ids"],
      "properties": {
        "value": {"type": "string", "minLength": 1},
        "status": {"enum": ["SUPPORTED", "SOURCE_REPORTED", "HYPOTHESIS", "UNKNOWN"]},
        "evidence_ids": {"$ref": "#/$defs/anchorList"},
        "visual_ids": {"$ref": "#/$defs/anchorList"}
      },
      "allOf": [
        {
          "if": {"properties": {"status": {"const": "UNKNOWN"}}},
          "then": {"properties": {"value": {"const": "UNKNOWN"}}}
        },
        {
          "if": {
            "properties": {"status": {"enum": ["SUPPORTED", "SOURCE_REPORTED"]}}
          },
          "then": {
            "anyOf": [
              {"properties": {"evidence_ids": {"minItems": 1}}},
              {"properties": {"visual_ids": {"minItems": 1}}}
            ]
          }
        }
      ]
    },
    "comparisonRow": {
      "type": "object",
      "additionalProperties": false,
      "required": ["dimension", "cells"],
      "properties": {
        "dimension": {"type": "string", "minLength": 1},
        "cells": {
          "type": "array",
          "minItems": 1,
          "items": {"$ref": "#/$defs/comparisonCell"}
        }
      }
    },
    "projection": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "projection_id",
        "projection_kind",
        "title",
        "relation_ids",
        "source_card_ids",
        "visual_evidence_ids",
        "uncertainty_policy",
        "options"
      ],
      "properties": {
        "projection_id": {"type": "string", "minLength": 1},
        "projection_kind": {
          "enum": ["causal-dataflow", "comparison-matrix", "timeline", "state-planes", "equation", "architecture"]
        },
        "title": {"type": "string", "minLength": 1},
        "relation_ids": {"$ref": "#/$defs/anchorList"},
        "source_card_ids": {"$ref": "#/$defs/anchorList"},
        "visual_evidence_ids": {"$ref": "#/$defs/anchorList"},
        "uncertainty_policy": {"enum": ["LABEL_UNKNOWN", "DOTTED_UNCERTAIN_EDGES", "OMIT_UNSUPPORTED_VALUES"]},
        "options": {"type": "object"}
      },
      "allOf": [
        {
          "if": {"properties": {"projection_kind": {"const": "comparison-matrix"}}},
          "then": {
            "properties": {
              "options": {
                "type": "object",
                "additionalProperties": false,
                "required": ["columns", "rows"],
                "properties": {
                  "columns": {
                    "type": "array",
                    "minItems": 2,
                    "items": {"type": "string", "minLength": 1}
                  },
                  "rows": {
                    "type": "array",
                    "minItems": 1,
                    "items": {"$ref": "#/$defs/comparisonRow"}
                  }
                }
              }
            }
          }
        },
        {
          "if": {"properties": {"projection_kind": {"const": "equation"}}},
          "then": {
            "properties": {
              "options": {
                "type": "object",
                "additionalProperties": false,
                "required": ["expression"],
                "properties": {"expression": {"type": "string", "minLength": 1}}
              }
            },
            "anyOf": [
              {"properties": {"relation_ids": {"minItems": 1}}},
              {"properties": {"visual_evidence_ids": {"minItems": 1}}}
            ]
          }
        },
        {
          "if": {
            "properties": {
              "projection_kind": {
                "enum": ["causal-dataflow", "timeline", "state-planes", "architecture"]
              }
            }
          },
          "then": {"properties": {"relation_ids": {"minItems": 1}}}
        }
      ]
    }
  }
}
